  const missing = nodes.some((n) => n.ui?.x == null || n.ui?.y == null);
  if (!missing) return;
  try {
    applyGraphAutoLayout(def);
  } catch (err) {
    console.error('[hadamard-gui] auto layout failed', err);
  }
