    edge.ui.sideLocked = true;
    if (isFrom) {
      edge.from = snap.ref;
      edge.ui.fromSide = snap.side;
      edge.ui.fromPort = snap.portIndex;
    } else {
      edge.to = snap.ref;
      edge.ui.toSide = snap.side;
      edge.ui.toPort = snap.portIndex;
    }
    const live = graphEdgeEndpoints(board, edge, idx);
    if (!live) return null;
